import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const a = second.split(" ").map(Number);

// 1 位と 2 位を持ちながら 1 回だけ走査する
let first = -Infinity;
let runnerUp = -Infinity;
for (const x of a) {
  if (x > first) {
    runnerUp = first;
    first = x;
  } else if (x > runnerUp) {
    runnerUp = x;
  }
}
console.log(runnerUp);
